import { z } from "zod";import { requireApiProfile } from "@/lib/access-control";import { recordBusinessAudit } from "@/lib/audit";import { db } from "@/lib/db";import { enforceSameOrigin,consumeRateLimit,rateLimitResponse,readJsonWithLimit,requestParseError } from "@/lib/http-security";import { hasFreshFinancialMfa } from "@/lib/mfa";
const schema=z.object({id:z.string().uuid().optional(),code:z.string().trim().min(1).max(40),name:z.string().trim().min(2).max(180),category:z.string().trim().max(100).optional(),contactName:z.string().trim().max(160).optional(),phone:z.string().trim().max(40).optional(),email:z.union([z.string().email().max(200),z.literal("")]).optional(),paymentTerms:z.string().trim().max(160).optional(),reliabilityPct:z.number().min(0).max(100).nullable().optional(),fillRatePct:z.number().min(0).max(100).nullable().optional(),active:z.boolean().default(true)});
export async function GET(){const a=await requireApiProfile("/api/vendors");if("response" in a)return a.response;const rows=await db()`SELECT * FROM vendors ORDER BY name`;return Response.json({rows},{headers:{"Cache-Control":"private, no-store"}})}
export async function POST(req:Request){return write(req)}export async function PATCH(req:Request){return write(req)}async function write(req:Request){const same=enforceSameOrigin(req);if(same)return same;const a=await requireApiProfile("/api/vendors");if("response" in a)return a.response;if(!(await hasFreshFinancialMfa()))return Response.json({error:"Fresh MFA required",code:"MFA_FRESH_REQUIRED"},{status:428});const lim=await consumeRateLimit("vendor-write",30,60,"user");if(!lim.allowed)return rateLimitResponse(lim.retryAfter);try{const p=schema.safeParse(await readJsonWithLimit(req,12000));if(!p.success)return Response.json({error:"Invalid vendor",issues:p.error.flatten()},{status:400});const v=p.data;const old=v.id?(await db()`SELECT * FROM vendors WHERE id=${v.id}`)[0] as any:null;const rows=v.id?await db()`UPDATE vendors SET code=${v.code.toUpperCase()},name=${v.name},category=${v.category||null},contact_name=${v.contactName||null},phone=${v.phone||null},email=${v.email||null},payment_terms=${v.paymentTerms||null},reliability_pct=${v.reliabilityPct??null},fill_rate_pct=${v.fillRatePct??null},active=${v.active},updated_at=NOW() WHERE id=${v.id} RETURNING *`:await db()`INSERT INTO vendors(code,name,category,contact_name,phone,email,payment_terms,reliability_pct,fill_rate_pct,active) VALUES(${v.code.toUpperCase()},${v.name},${v.category||null},${v.contactName||null},${v.phone||null},${v.email||null},${v.paymentTerms||null},${v.reliabilityPct??null},${v.fillRatePct??null},${v.active}) ON CONFLICT(code) DO UPDATE SET name=EXCLUDED.name,category=EXCLUDED.category,contact_name=EXCLUDED.contact_name,phone=EXCLUDED.phone,email=EXCLUDED.email,payment_terms=EXCLUDED.payment_terms,reliability_pct=EXCLUDED.reliability_pct,fill_rate_pct=EXCLUDED.fill_rate_pct,active=EXCLUDED.active,updated_at=NOW() RETURNING *`;if(!rows.length)return Response.json({error:"Vendor not found"},{status:404});const r=rows[0] as any;await recordBusinessAudit({actorUserId:a.profile.id,action:old?"update":"create",entityType:"vendor",entityId:String(r.id),oldValues:old,newValues:r});return Response.json({ok:true,row:r});}catch(e){const r=requestParseError(e);if(r)return r;throw e;}}
